<?php if(!defined('SW_APP')||!SW_PUBLIC||!$u||!profile_complete($u)){http_response_code(403);exit;} $tab=$_GET['tab']??'sorteos';$modules=['sorteos'=>'Sorteos activos','boletos'=>'Mis boletos','premios'=>'Mis premios','pagos'=>'Mis pagos','transacciones'=>'Transacciones','recargar'=>'Añadir dinero','numeros'=>'Seleccionar boleto'];if(!is_string($tab)||!isset($modules[$tab]))$tab='sorteos';require_once dirname(__DIR__).'/wallet/service.php';$walletAvailable=wallet_ready();$walletTotals=$walletAvailable?wallet_totals((int)$u['id']):null;pub_head('Mi cuenta',$u); ?>
<main class="public-wrap user-shell"><aside class="user-nav"><div class="user-ident"><span class="user-avatar"><?=h(preg_match('/^./u',$u['first_names'],$initial)?$initial[0]:'U')?></span><strong><?=h($u['first_names'].' '.$u['last_names'])?></strong><small><?=h($u['email'])?></small></div><div class="wallet-sidebar"><span>Saldo disponible</span><strong><?=$walletTotals!==null?money($walletTotals['balance']):'No disponible'?></strong><a class="pub-btn primary" href="<?=h(pub_url('account',['tab'=>'recargar']))?>"><span aria-hidden="true">＋</span> Añadir dinero</a></div><nav aria-label="Mi cuenta"><?php foreach($modules as $k=>$label):if(in_array($k,['recargar','numeros'],true))continue;?><a class="<?=($tab===$k||($tab==='numeros'&&$k==='sorteos'))?'selected':''?>" href="<?=h(pub_url('account',['tab'=>$k]))?>"><?=h($label)?></a><?php endforeach;?><a href="<?=h(pub_url('profile'))?>">Mi perfil</a></nav><form method="post" action="<?=h(pub_url('account'))?>"><?=csrf()?><input type="hidden" name="action" value="public_logout"><button class="pub-btn secondary" type="submit">Cerrar sesión</button></form></aside><section class="user-content"><?php pub_notice();?><p class="eyebrow">MI CUENTA</p><h1><?=h($modules[$tab])?></h1><?php require __DIR__.'/modules/'.$tab.'.php';?></section></main><?php pub_footer(); ?>
